from lib import *
S = SS('v33')
steps = [
    step("鉴权带来多少延迟。500 个顺序请求,带有效 JWT。不鉴权:延迟中位数 0.15 ms,p99 0.54 ms。nginx auth_request(鉴权服务回得很快):0.32 ms,p99 0.51 ms,鉴权服务被调用 500 次。auth_request(鉴权服务要 20 ms):29.34 ms,p99 33.15 ms,500 次——每个请求都多等一次鉴权。auth_request 加缓存 5 s(按 Authorization 头缓存,鉴权服务 20 ms):0.17 ms,p99 0.57 ms,鉴权服务只被调用 1 次。Envoy 本地 jwt_authn:0.18 ms,p99 0.34 ms,不访问任何鉴权服务。", t=tl(S(1)), mark=lidx(S(1), '鉴权服务 20 ms)'), done=lidx(S(1), '不鉴权', '缓存 5 s', 'Envoy'), b=bars([['不鉴权:中位数 ms', 0.15, '0.15'], ['auth_request 20 ms:中位数 ms', 29.34, '29.34'], ['auth_request + 缓存:中位数 ms', 0.17, '0.17(鉴权服务调用 1 次)'], ['Envoy jwt_authn:中位数 ms', 0.18, '0.18']], 30, mark=[1], done=[0, 2, 3]), kv=KV([['auth_request(20 ms 的鉴权服务)', '每个请求 +29 ms,鉴权服务调用 500 次'], ['加缓存 5 s', '中位数 0.17 ms,调用 1 次'], ['本地 jwt_authn', '0.18 ms,不依赖外部']], ['auth_request(20 ms 的鉴权服务)'])),
    step("撤销令牌后多久生效。令牌有效期 12 秒,第 3 秒把它加入撤销名单。auth_request 无缓存:撤销立刻生效,0.00 s 后第一个请求就被拒,撤销之后 0 个请求被放行。auth_request 缓存 5 s:撤销之后又放行了 10 个请求,最后一个在撤销后 2.34 s,第一个被拒在 2.60 s。Envoy 本地 jwt_authn(网关不知道撤销名单):clock_skew_seconds 保持默认时,整个 14.5 秒的测试里令牌一直被放行(撤销之后 45 个请求通过,没有拒绝),因为默认允许令牌过期之后再宽限一段时间;设 clock_skew_seconds: 1 后,令牌过期时才被拒,撤销之后仍有 42 个请求被放行,最后一个在撤销后 10.60 s(0 表示用默认值,不能关掉宽限)。", t=tl(S(2)), mark=lidx(S(2), 'Envoy'), done=lidx(S(2), 'auth_request 无缓存', 'auth_request 缓存'), b=bars([['auth_request 无缓存:撤销后仍放行', 0, '0 个'], ['auth_request 缓存 5 s:撤销后仍放行', 10, '10 个(2.34 s)'], ['Envoy skew 1:撤销后仍放行', 42, '42 个(10.60 s)'], ['Envoy 默认 skew:撤销后仍放行', 45, '45 个(一直不拒)']], 45, done=[0, 1], mark=[2, 3]), kv=KV([['auth_request 无缓存', '撤销立刻生效'], ['加缓存 5 s', '最长 5 s 延迟(这里 2.60 s)'], ['本地 JWT', '撤销无效,等令牌过期;默认还多宽限一段']], ['本地 JWT'])),
    step("鉴权服务挂了(第 2 秒停掉),client 每 20 ms 一个请求,每秒 50 个。auth_request 无缓存:第 0、1 秒 50/0,第 2 秒起全是 0/50。auth_request 缓存 5 s 且加 proxy_cache_use_stale error timeout:6 秒一直 50/0,过期的缓存继续被用,请求一直放行(撤销和封禁也都不再生效)。auth_request 缓存 5 s、不允许用过期缓存:前 5 秒 50/0,第 5 秒缓存过期,16/34。Envoy 本地 jwt_authn:6 秒都是 50/0,鉴权服务关不关都不影响。", t=tl(S(3)), mark=lidx(S(3), '无缓存', '不允许用过期缓存'), done=lidx(S(3), 'use_stale', 'Envoy'), b=bars([['无缓存 第 3 秒 放行', 0, '0 / 50'], ['缓存(不允许过期)第 5 秒 放行', 16, '16 / 50'], ['缓存 + use_stale 第 5 秒 放行', 50, '50 / 50'], ['Envoy 第 5 秒 放行', 50, '50 / 50']], 50, mark=[0, 1], done=[2, 3]), kv=KV([['无缓存', '鉴权服务一挂立刻全失败'], ['缓存不允许过期', '5 秒后一起失败'], ['缓存 + use_stale', '一直放行,撤销不再生效']], ['缓存 + use_stale'])),
    step("client 伪造身份头。client 带有效令牌(sub = alice),同时伪造 X-User: admin。nginx (a) 不覆盖 X-User:后端回 hello admin——伪造的身份被后端当真。nginx (b) proxy_set_header X-User $auth_user(用鉴权服务返回的值覆盖):后端回 hello alice。Envoy jwt_authn 只验证令牌、没有配置覆盖:后端回 hello admin。网关鉴权通过后,要用网关自己确认的身份覆盖发给后端的头,并丢掉 client 发来的同名头。", t=tl(S(4)), mark=lidx(S(4), '(a)', 'Envoy'), done=lidx(S(4), '(b)'), b=bars([['nginx 不覆盖:后端看到', 1, 'admin(伪造)'], ['nginx 覆盖 $auth_user:后端看到', 1, 'alice'], ['Envoy 没配覆盖:后端看到', 1, 'admin(伪造)']], 1, mark=[0, 2], done=[1]), kv=KV([['不覆盖', '后端信了伪造的 admin'], ['proxy_set_header X-User $auth_user', '后端看到 alice'], ['Envoy jwt_authn', '只验证,不改写头']], ['不覆盖'])),
]
